namespace sv_0235c5e763ab4683a274f5507f6ba171.Services;

public class AppointmentService
{
    private static readonly List<string> Doctors = new()
    {
        "Dr. Smith",
        "Dr. Johnson",
        "Dr. Williams",
        "Dr. Brown"
    };

    private static readonly List<string> AllTimeSlots = new()
    {
        "9:00 AM",
        "10:00 AM",
        "11:00 AM",
        "1:00 PM",
        "2:00 PM",
        "3:00 PM",
        "4:00 PM"
    };

    public Task<List<string>> GetDoctorsAsync()
    {
        return Task.FromResult(Doctors);
    }

    public Task<List<string>> GetAvailableTimeSlotsAsync(string doctor, DateTime date)
    {
        // Stub: return all time slots regardless of doctor/date
        return Task.FromResult(new List<string>(AllTimeSlots));
    }

    /// <summary>
    /// Validates patient information server-side.
    /// Returns a dictionary of field name -> error message for any validation failures.
    /// </summary>
    public Task<Dictionary<string, string>> ValidatePatientAsync(
        string email,
        string insuranceProvider,
        string doctor,
        string timeSlot)
    {
        var errors = new Dictionary<string, string>();

        // Reject patients with outstanding balance
        if (string.Equals(email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            errors[nameof(email)] = "Account has outstanding balance";
        }

        // Reject self-pay with Dr. Smith
        if (string.Equals(insuranceProvider, "None", StringComparison.Ordinal)
            && string.Equals(doctor, "Dr. Smith", StringComparison.Ordinal))
        {
            errors[nameof(doctor)] = "Selected doctor does not accept self-pay patients";
        }

        // Simulate race condition on 10:00 AM slot
        if (string.Equals(timeSlot, "10:00 AM", StringComparison.Ordinal))
        {
            errors[nameof(timeSlot)] = "This slot is no longer available";
        }

        return Task.FromResult(errors);
    }
}

@page "/book-appointment"
@rendermode InteractiveServer
@using sv_0235c5e763ab4683a274f5507f6ba171.Services
@inject AppointmentService AppointmentSvc

<PageTitle>Book Appointment</PageTitle>

<h1>Book an Appointment</h1>

<EditForm Model="Model" OnValidSubmit="HandleSubmit">
    <DataAnnotationsValidator />

    @* STEP 1 *@
    <fieldset>
        <legend>Step 1: Patient Information</legend>

        <div class="mb-3">
            <label for="patientName">Patient Name</label>
            <InputText id="patientName" class="form-control" @bind-Value="Model.PatientName" />
            <ValidationMessage For="() => Model.PatientName" />
        </div>

        <div class="mb-3">
            <label for="email">Email</label>
            <InputText id="email" class="form-control" @bind-Value="Model.Email" />
            <ValidationMessage For="() => Model.Email" />
            @if (_serverErrors.ContainsKey("email"))
            {
                <div class="validation-message">@_serverErrors["email"]</div>
            }
        </div>

        <div class="mb-3">
            <label for="phone">Phone</label>
            <InputText id="phone" class="form-control" @bind-Value="Model.Phone" />
            <ValidationMessage For="() => Model.Phone" />
        </div>

        <div class="mb-3">
            <label for="insurance">Insurance Provider</label>
            <InputSelect id="insurance" class="form-control" @bind-Value="Model.InsuranceProvider">
                <option value="">-- Select --</option>
                <option value="Aetna">Aetna</option>
                <option value="BlueCross">BlueCross</option>
                <option value="Cigna">Cigna</option>
                <option value="UnitedHealth">UnitedHealth</option>
                <option value="None">None</option>
            </InputSelect>
            <ValidationMessage For="() => Model.InsuranceProvider" />
        </div>
    </fieldset>

    @if (!_showStep2)
    {
        <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">Next</button>
    }

    @* STEP 2 *@
    @if (_showStep2)
    {
        <fieldset class="mt-4">
            <legend>Step 2: Appointment Details</legend>

            <div class="mb-3">
                <label for="doctor">Preferred Doctor</label>
                <InputSelect id="doctor" class="form-control" @bind-Value="Model.Doctor" ValueChanged="OnDoctorChanged" ValueExpression="() => Model.Doctor">
                    <option value="">-- Select --</option>
                    @foreach (var doc in _doctors)
                    {
                        <option value="@doc">@doc</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.Doctor" />
                @if (_serverErrors.ContainsKey("doctor"))
                {
                    <div class="validation-message">@_serverErrors["doctor"]</div>
                }
            </div>

            <div class="mb-3">
                <label for="date">Date</label>
                <InputDate id="date" class="form-control" @bind-Value="Model.AppointmentDate" />
                <ValidationMessage For="() => Model.AppointmentDate" />
            </div>

            <div class="mb-3">
                <label for="timeSlot">Time Slot</label>
                <InputSelect id="timeSlot" class="form-control" @bind-Value="Model.TimeSlot">
                    <option value="">-- Select --</option>
                    @foreach (var slot in _timeSlots)
                    {
                        <option value="@slot">@slot</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.TimeSlot" />
                @if (_serverErrors.ContainsKey("timeSlot"))
                {
                    <div class="validation-message">@_serverErrors["timeSlot"]</div>
                }
            </div>

            <div class="mb-3">
                <label for="reason">Reason for Visit</label>
                <InputTextArea id="reason" class="form-control" @bind-Value="Model.Reason" />
                <ValidationMessage For="() => Model.Reason" />
            </div>

            <button type="button" class="btn btn-secondary me-2" @onclick="CheckAvailability" disabled="@_isChecking">
                @(_isChecking ? "Checking..." : "Check Availability")
            </button>

            @if (_availabilityConfirmed)
            {
                <button type="submit" class="btn btn-success">Confirm Appointment</button>
            }
        </fieldset>
    }

    @if (_submitted)
    {
        <div class="alert alert-success mt-3">Appointment booked successfully!</div>
    }
</EditForm>

@code {
    private AppointmentModel Model { get; set; } = new();
    private bool _showStep2;
    private bool _isChecking;
    private bool _availabilityConfirmed;
    private bool _submitted;
    private List<string> _doctors = new();
    private List<string> _timeSlots = new();
    private Dictionary<string, string> _serverErrors = new();

    protected override async Task OnInitializedAsync()
    {
        _doctors = await AppointmentSvc.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        // Validate step 1 fields manually
        _serverErrors.Clear();
        _availabilityConfirmed = false;

        if (string.IsNullOrWhiteSpace(Model.PatientName)
            || string.IsNullOrWhiteSpace(Model.Email)
            || !IsValidEmail(Model.Email)
            || string.IsNullOrWhiteSpace(Model.Phone)
            || string.IsNullOrWhiteSpace(Model.InsuranceProvider))
        {
            // Let DataAnnotationsValidator show errors via EditContext
            return;
        }

        _showStep2 = true;
    }

    private async Task OnDoctorChanged(string value)
    {
        Model.Doctor = value;
        _availabilityConfirmed = false;
        _serverErrors.Remove("doctor");

        if (!string.IsNullOrEmpty(value) && Model.AppointmentDate.HasValue)
        {
            _timeSlots = await AppointmentSvc.GetAvailableTimeSlotsAsync(value, Model.AppointmentDate.Value);
        }
    }

    private async Task CheckAvailability()
    {
        _serverErrors.Clear();
        _availabilityConfirmed = false;
        _isChecking = true;

        try
        {
            var errors = await AppointmentSvc.ValidatePatientAsync(
                Model.Email,
                Model.InsuranceProvider,
                Model.Doctor ?? "",
                Model.TimeSlot ?? "");

            if (errors.Count > 0)
            {
                _serverErrors = errors;
            }
            else
            {
                _availabilityConfirmed = true;
            }
        }
        finally
        {
            _isChecking = false;
        }
    }

    private void HandleSubmit()
    {
        if (_availabilityConfirmed)
        {
            _submitted = true;
        }
    }

    private static bool IsValidEmail(string email)
    {
        try
        {
            var addr = new System.Net.Mail.MailAddress(email);
            return addr.Address == email;
        }
        catch
        {
            return false;
        }
    }
}

using System.ComponentModel.DataAnnotations;

namespace sv_0235c5e763ab4683a274f5507f6ba171.Components.Pages;

public class AppointmentModel
{
    // Step 1
    [Required(ErrorMessage = "Patient name is required")]
    public string PatientName { get; set; } = "";

    [Required(ErrorMessage = "Email is required")]
    [EmailAddress(ErrorMessage = "Invalid email format")]
    public string Email { get; set; } = "";

    [Required(ErrorMessage = "Phone is required")]
    public string Phone { get; set; } = "";

    [Required(ErrorMessage = "Insurance provider is required")]
    public string InsuranceProvider { get; set; } = "";

    // Step 2
    [Required(ErrorMessage = "Please select a doctor")]
    public string? Doctor { get; set; }

    [Required(ErrorMessage = "Date is required")]
    [FutureDate(ErrorMessage = "Date must be in the future")]
    public DateTime? AppointmentDate { get; set; }

    [Required(ErrorMessage = "Please select a time slot")]
    public string? TimeSlot { get; set; }

    [Required(ErrorMessage = "Reason for visit is required")]
    [MaxLength(500, ErrorMessage = "Reason cannot exceed 500 characters")]
    public string? Reason { get; set; }
}

public class FutureDateAttribute : ValidationAttribute
{
    protected override ValidationResult? IsValid(object? value, ValidationContext validationContext)
    {
        if (value is DateTime date && date.Date <= DateTime.Today)
        {
            return new ValidationResult(ErrorMessage);
        }
        return ValidationResult.Success;
    }
}

